class Store extends ChangeNotifier{SharedPreferences? p;List<Map<String,dynamic>> shops=[];int active=0;bool get ready=>p!=null;bool get has=>shops.isNotEmpty;Map<String,dynamic> get shop=>has?shops[active]:{};List<Map<String,dynamic>> rows(String k){final v=shop[k];if(v is! List)return[];return v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}Future<void> load()async{p=await SharedPreferences.getInstance();try{final x=jsonDecode(p!.getString('rentflow')??'[]');if(x is List)shops=x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];}active=p!.getInt('active')??0;if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;notifyListeners();}Future<void> save()async{await p!.setString('rentflow',jsonEncode(shops));await p!.setInt('active',active);notifyListeners();}Future<void> addShop(Map<String,dynamic>x)async{shops.add({...x,'id':uid(),'items':[],'customers':[],'issues':[],'returns':[]});active=shops.length-1;await save();}Future<void> editShop(int i,Map<String,dynamic>x)async{shops[i].addAll(x);await save();}Future<void> deleteShop(int i)async{shops.removeAt(i);active=shops.isEmpty?0:(active>=shops.length?shops.length-1:active);await save();}Future<void> add(String k,Map<String,dynamic>x)async{final v=shop[k];if(v is List)v.add(x);await save();}Future<void> edit(String k,int i,Map<String,dynamic>x)async{final v=shop[k];if(v is List&&i<v.length)v[i]=x;await save();}Future<void> del(String k,int i)async{final v=shop[k];if(v is List&&i<v.length)v.removeAt(i);await save();}}
Future<T?> openPage<T>(BuildContext c,Widget w)=>Navigator.push<T>(c,MaterialPageRoute(builder:(_)=>w));

