Future<void> printPdf(Map<String,dynamic>x,String type)async{final doc=pw.Document();final items=x['items'] is List?(x['items'] as List).whereType<Map>().toList():<Map>[];doc.addPage(pw.Page(pageFormat:PdfPageFormat.a4,build:(_)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('RentFlow',style:pw.TextStyle(fontSize:22,fontWeight:pw.FontWeight.bold)),pw.Text('By PaliaAPK HUB • Developer by shanpalia'),pw.SizedBox(height:12),pw.Text('$type Entry'),pw.Text('Invoice: ${x['invoice']??'-'}'),pw.Text('Date: ${x['date']??'-'}'),pw.Text('Customer: ${x['customerName']??'-'}'),pw.SizedBox(height:12),pw.TableHelper.fromTextArray(headers:['Srl','Item','Qty','Unit'],data:[for(int i=0;i<items.length;i++)['${i+1}','${items[i]['name']??''}','${type=='Return'?(items[i]['returnQty']??items[i]['quantity']??0):(items[i]['quantity']??0)}','${items[i]['unit']??'pcs'}']]),if(type=='Return')pw.Padding(padding:const pw.EdgeInsets.only(top:10),child:pw.Text('Manual Amount: ${x['amount']??0}'))])));await Printing.layoutPdf(onLayout:(_)=>doc.save());}
